insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos responsáveis pela investigação, persecução penal e inteligência poderão atuar de forma conjunta e coordenada em forças-tarefa integradas, para o planejamento e a execução de ações estratégicas contra organizações ultraviolentas, grupos paramilitares e milícias. A criação das forças-tarefa será formalizada por termo de cooperação. A atuação compreende o compartilhamento seguro de dados e inteligência, operações conjuntas e apoio mútuo, sob regime de sigilo. As medidas judiciais correlatas serão requeridas e decididas sob sigilo. O descumprimento não gera nulidade das provas. A Força Integrada poderá contar com o Ministério Público Federal e os Ministérios Públicos estaduais e distrital, inclusive por seus Gaecos, preservada sua independência funcional.', '["Forças-tarefa integradas entre órgãos de investigação e inteligência.","Termo de cooperação.","Compartilhamento de dados e operações conjuntas, com sigilo.","Medidas judiciais sob sigilo e tramitação célere.","Descumprimento não gera nulidade.","Participação de MPs e Gaecos."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Respeita as atribuições constitucionais de cada órgão."]'::jsonb, 'Polícia Federal, polícias estaduais e Gaeco formam uma força-tarefa para desarticular uma facção.', '["Assertiva que torna nula a prova por descumprimento das regras da força-tarefa erra: o §5º afasta a nulidade."]'::jsonb, '[{"termo":"Gaeco","significado":"Grupo de Atuação Especial de Combate ao Crime Organizado."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando as condutas da Lei apresentarem caráter transnacional ou envolverem a cooperação de organizações estrangeiras, a União poderá, por intermédio dos órgãos competentes, celebrar e executar acordos de cooperação internacional policial ou de inteligência, observados os tratados, as convenções e os princípios de reciprocidade, para investigação, persecução penal, extradição, recuperação de ativos e combate à criminalidade organizada de alcance internacional.', '["Cooperação internacional policial ou de inteligência.","Quando houver caráter transnacional ou cooperação de organizações estrangeiras.","Respeita tratados e reciprocidade."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","A competência é da União."]'::jsonb, 'A União firma acordo com outro país para rastrear ativos de uma facção.', '["Assertiva que atribui aos Estados a celebração de acordos de cooperação internacional erra: é da União."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na apuração e na instrução processual dos crimes da Lei, aplicam-se, no que couber, as disposições referentes às organizações criminosas quanto à investigação e aos meios de obtenção da prova, nos termos do Capítulo II da Lei de Organizações Criminosas, bem como as disposições da Lei de Lavagem de Dinheiro.', '["Aplicam-se os meios de obtenção de prova da Lei de Organizações Criminosas.","Aplica-se também a Lei de Lavagem."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Colaboração premiada, ação controlada e infiltração estão disponíveis."]'::jsonb, 'A polícia pode usar colaboração premiada e infiltração para investigar a facção.', '["Assertiva que afasta a Lei de Organizações Criminosas da investigação dos crimes desta Lei erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, a requerimento do Ministério Público ou por representação do delegado, havendo indícios suficientes de que o agente tenha praticado crime dos arts. 2º e 3º, poderá decretar, no curso da investigação ou da ação penal, medidas assecuratórias como sequestro, arresto, bloqueio de bens móveis e imóveis, inclusive ativos virtuais, no País ou no exterior; suspensão de atividades econômicas; bloqueio de acesso a sistemas financeiros e plataformas; proibição de instrumentos de crédito e transferências, inclusive Pix; comunicação ao Coaf, Banco Central, CVM, Susep e Receita; suspensão de serviços usados no crime; afastamento do cargo com remuneração; proibição de saída do País e apreensão de passaporte; bloqueio de transferência de propriedade; e inidoneidade cautelar para contratar com o poder público. As medidas podem ser decretadas sem prévia oitiva, com contraditório diferido. Decretada a medida, o investigado pode, em 10 dias, provar a origem lícita; comprovada a origem lícita, o bem é liberado, exceto armas de fogo. Se clara a origem ilícita, pode haver perdimento extraordinário, independentemente de condenação penal, ressalvado o terceiro de boa-fé. Em caso de absolvição, o valor é devolvido em até 3 dias úteis com juros. As decisões são sigilosas até o cumprimento, e há supervisão do CNJ e do CNMP.', '["Rol exemplificativo de medidas assecuratórias patrimoniais e restritivas.","Podem ser decretadas sem oitiva prévia (contraditório diferido).","Investigado tem 10 dias para provar a origem lícita.","Perdimento extraordinário, independentemente de condenação, se clara a origem ilícita.","Absolvição: devolução em até 3 dias úteis.","Sigilo e supervisão do CNJ e CNMP."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Perdimento extraordinário NÃO depende de condenação penal (exige origem clara ilícita).","Fundamentação da necessidade, adequação e proporcionalidade é obrigatória."]'::jsonb, 'O juiz bloqueia contas e criptoativos do líder e de laranjas, e eles têm 10 dias para provar a origem lícita.', '["Assertiva que condiciona o perdimento extraordinário à condenação transitada em julgado erra: o §8º dispensa a condenação."]'::jsonb, '[{"termo":"Contraditório diferido","significado":"A defesa se manifesta depois da decisão."}]'::jsonb, '["Art. 11","Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No curso da investigação, havendo indícios concretos de que uma pessoa jurídica esteja sendo beneficiada por organização ultraviolenta, o juiz determinará, a requerimento do MP ou por representação do delegado, o imediato afastamento dos sócios e a intervenção judicial na administração, como medida assecuratória cautelar. A intervenção visa interromper a atividade criminosa, preservar empregos e contratos de boa-fé e assegurar a destinação lícita dos bens. Acarreta o bloqueio de operações financeiras até a nomeação do interventor, que terá idoneidade, qualificação e experiência e administrará a empresa por seis meses, prorrogáveis. O interventor pode suspender contratos suspeitos, rescindir vínculos, auditar, identificar bens ilícitos, propor plano de saneamento ou liquidação e destinar recursos à conta judicial. Contratos públicos podem ser suspensos, e a empresa fica impedida de contratar com o poder público. O interventor presta contas trimestrais. O produto da venda antecipada vai ao Fundo de Segurança Pública do Estado, ao Fundo Nacional ou é rateado. Concluída a intervenção, o juiz decide pela restituição aos sócios de boa-fé, liquidação ou perdimento total. Bens ligados ao tráfico de drogas seguem a legislação específica.', '["Afastamento dos sócios e intervenção judicial na empresa beneficiada.","Interventor por seis meses, prorrogáveis.","Prestação de contas trimestral.","Contratos públicos suspensos; empresa impedida de contratar.","Destino dos recursos conforme quem investiga (Estado, Fundo Nacional ou rateio).","Fim da intervenção: restituição, liquidação ou perdimento total."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Preserva empregos e contratos de boa-fé.","Tráfico de drogas segue regime próprio."]'::jsonb, 'Uma transportadora usada pela facção é colocada sob intervenção judicial, com interventor nomeado pelo juiz.', '["Assertiva que fixa a intervenção por prazo indeterminado e sem prestação de contas erra: seis meses prorrogáveis, com contas trimestrais."]'::jsonb, '[{"termo":"Interventor judicial","significado":"Profissional nomeado pelo juiz para administrar a empresa."}]'::jsonb, '["Art. 9º","Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após o trânsito em julgado da sentença condenatória por crime dos arts. 2º e 3º, se não houve o perdimento extraordinário, o juiz determinará medidas patrimoniais e restritivas para a desarticulação financeira definitiva da organização, como a conversão automática das medidas cautelares em perda definitiva, ainda que em nome de terceiros; o confisco ampliado de bens incompatíveis com a renda declarada nos 5 anos anteriores ao fato; a dissolução compulsória da empresa e a responsabilidade solidária dos sócios; a liquidação judicial com destinação aos fundos de segurança pública; a afetação imediata dos bens apreendidos ao uso de órgãos de segurança; a proibição definitiva de contratar com o poder público por 12 a 15 anos; o cancelamento de autorizações e licenças; a responsabilidade solidária e sucessória de sócios e herdeiros até o limite do proveito; comunicações obrigatórias aos órgãos de controle e cartórios; e a publicação das condenações em cadastro público nacional. Os bens perdidos podem ser usados provisoriamente pelos órgãos de segurança. As medidas têm natureza de execução penal patrimonial e não dependem de nova ação civil.', '["Medidas após o trânsito em julgado da condenação.","Confisco ampliado dos bens incompatíveis com a renda nos 5 anos anteriores.","Dissolução da empresa e responsabilidade solidária.","Destinação aos fundos de segurança pública.","Proibição de contratar com o poder público por 12 a 15 anos.","Execução penal patrimonial, sem nova ação civil."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Confisco ampliado: janela de 5 anos anteriores ao fato."]'::jsonb, 'Após a condenação do líder, bens incompatíveis com sua renda são perdidos em favor do Estado.', '["Assertiva que exige ação civil própria para as medidas do art. 11 erra: são execução penal patrimonial."]'::jsonb, '[{"termo":"Confisco ampliado","significado":"Perda de bens incompatíveis com a renda lícita do condenado."}]'::jsonb, '["Art. 9º","Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os crimes da Lei, fica instituída a ação civil autônoma de perdimento de bens, que tem por objeto a extinção dos direitos de posse e propriedade e de todos os demais direitos reais ou pessoais sobre bens ou valores que sejam produto ou proveito, direto ou indireto, de atividade ilícita ou a ela relacionados, com transferência em favor da União, dos Estados, do Distrito Federal ou dos Municípios, sem direito a indenização. A perda abrange coisas corpóreas e incorpóreas e seus frutos. Pode ser decretada a perda de bens equivalentes quando o produto não for encontrado ou estiver no exterior. A ação civil de perdimento é imprescritível.', '["Ação civil autônoma de perdimento de bens.","Extingue direitos sobre bens ligados à atividade ilícita, sem indenização.","Abrange bens corpóreos e incorpóreos e seus frutos.","Perda por equivalente.","Imprescritível."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","A ação é CIVIL e autônoma da ação penal.","Imprescritível."]'::jsonb, 'O Estado ajuíza ação civil para tomar imóvel comprado com dinheiro da facção.', '["Assertiva que sujeita a ação civil de perdimento a prazo prescricional erra: é imprescritível."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A perda civil de bens será declarada nas hipóteses em que o bem, direito, valor, patrimônio ou seu incremento proceda dos crimes da Lei; seja usado como meio ou instrumento; esteja relacionado ou destinado à prática; seja usado para ocultar bens oriundos dos crimes; ou proceda de alienação ou permuta com bens nessas hipóteses. A transmissão a terceiros não obsta a perda. Não se aplica ao lesado e ao terceiro interessado que, de boa-fé, não tinham condições de conhecer a procedência, a utilização ou a destinação ilícita do bem.', '["Bens procedentes, instrumentos, destinados ao crime, usados para ocultação ou obtidos em trocas desses bens.","A transmissão a terceiros não impede a perda.","Ressalva do lesado e do terceiro de boa-fé."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","O terceiro de boa-fé é protegido."]'::jsonb, 'O carro comprado com recursos do crime e depois repassado a um parente pode ser perdido.', '["Assertiva que protege o terceiro mesmo de má-fé erra: a ressalva é só para a boa-fé."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá a perda civil de bens, direitos ou valores situados no Brasil, ainda que a atividade ilícita tenha sido praticada no exterior. Na falta de tratado, os bens objeto da perda civil por solicitação de autoridade estrangeira, ou os recursos de sua alienação, serão repartidos em partes iguais entre o Brasil e o Estado requerente. Antes da repartição, serão deduzidas as despesas de guarda, manutenção, alienação ou devolução.', '["Perda de bens situados no Brasil, ainda que o crime tenha ocorrido no exterior.","Sem tratado, repartição em partes iguais com o Estado requerente.","Dedução das despesas antes da repartição."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'O dinheiro de um crime no exterior que está em banco brasileiro pode ser perdido e dividido com o país requerente.', '["Assertiva que repassa ao Estado estrangeiro todo o valor erra: a divisão é em partes iguais, descontadas as despesas."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público e o órgão de representação judicial da pessoa jurídica legitimada, da administração direta ou indireta da União, dos Estados, do Distrito Federal ou dos Municípios poderão instaurar procedimento preparatório para o ajuizamento de ação declaratória de perda civil da propriedade ou da posse. O MP poderá requisitar, e o órgão de representação poderá solicitar, de qualquer órgão ou banco de dados público, certidões, informações, exames e perícias, no prazo que assinalar, conforme a urgência e a complexidade.', '["Procedimento preparatório para a ação de perda civil.","Legitimados: Ministério Público e órgãos de representação judicial dos entes.","Poder de requisitar certidões, informações e perícias."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'O Ministério Público abre procedimento preparatório e requisita certidões antes de propor a ação de perdimento.', '["Assertiva que restringe a instauração do procedimento à polícia erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O órgão ou entidade pública que verificar indícios de que bens, direitos ou valores se encontrem nas hipóteses de perda civil deverá comunicar o fato ao Ministério Público e ao órgão de representação judicial da pessoa jurídica de direito público a que estiver vinculado. Verificado o interesse de outra pessoa jurídica de direito público, as informações serão compartilhadas com o respectivo MP e órgão de representação judicial.', '["Dever de comunicar indícios ao Ministério Público e ao órgão de representação.","Compartilhamento com outros entes interessados."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","A comunicação é um DEVER do órgão que detecta os indícios."]'::jsonb, 'A Receita identifica patrimônio suspeito e informa o Ministério Público.', '["Assertiva que torna facultativa a comunicação ao MP erra: o dispositivo diz ''deverá''."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A declaração de perda civil independe da aferição de responsabilidade civil ou criminal, bem como do desfecho das respectivas ações civis ou penais, ressalvada a sentença penal absolutória que taxativamente reconheça a inexistência do fato. Se o pedido de perdimento for julgado, em definitivo, improcedente por insuficiência de provas, qualquer legitimado poderá propor outra ação com idêntico fundamento, valendo-se de nova prova.', '["A perda civil independe de responsabilização civil ou penal.","Exceção: sentença penal absolutória que reconheça a inexistência do fato.","Improcedência por falta de provas permite nova ação com nova prova."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Independência em relação ao desfecho penal."]'::jsonb, 'Mesmo sem condenação, o Estado pode buscar o perdimento do patrimônio ilícito.', '["Assertiva que condiciona a perda civil à condenação penal erra: ela independe do desfecho penal."]'::jsonb, '[]'::jsonb, '["Art. 12","Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ação será proposta pela União, pelos Estados, pelo Distrito Federal ou pelos Municípios e pelas respectivas entidades da administração indireta; pelo Ministério Público Federal nos casos de competência cível da Justiça Federal; e pelo Ministério Público dos Estados ou do Distrito Federal e Territórios nos demais casos. Quando não for autor, o Ministério Público intervirá obrigatoriamente como fiscal da ordem jurídica, podendo aditar a petição inicial e, em caso de desistência ou abandono, assumir a titularidade ativa.', '["Legitimados: entes federativos e suas entidades; MPF; MPs estaduais e do DF.","MP intervém como fiscal da ordem jurídica quando não for autor.","Pode aditar a inicial e assumir a titularidade em caso de abandono."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'Se o Estado desiste da ação, o Ministério Público pode assumi-la.', '["Assertiva que torna facultativa a intervenção do MP como fiscal da ordem jurídica erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Figurará no polo passivo da ação o titular ou possuidor dos bens, direitos ou valores. O preposto, gerente ou administrador de pessoa jurídica estrangeira presume-se autorizado a receber a citação inicial.', '["Réu: titular ou possuidor dos bens.","Citação de pessoa jurídica estrangeira pelo preposto, gerente ou administrador."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","A ação é contra o BEM e seu titular, e não contra o criminoso."]'::jsonb, 'A empresa dona do imóvel é citada como ré na ação de perdimento.', '["Assertiva que exige que o réu seja o condenado penal erra: figura o titular ou possuidor dos bens."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se não for possível determinar o proprietário ou o possuidor, figurarão no polo passivo réus incertos, citados por edital, do qual constará a descrição dos bens. Quando qualquer pessoa se apresentar como titular dos bens, poderá ingressar no polo passivo, recebendo o processo no estado em que se encontra. Aos réus incertos será nomeado curador especial, mesmo na hipótese de ingresso de titular.', '["Réus incertos citados por edital com descrição dos bens.","Quem se apresentar como titular entra no estado em que o processo se encontra.","Curador especial para os réus incertos."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'Dinheiro apreendido sem dono identificado leva à citação por edital de réus incertos.', '["Assertiva que dispensa curador especial aos réus incertos erra."]'::jsonb, '[{"termo":"Réus incertos","significado":"Pessoas não identificadas que possam ter direito sobre os bens."}]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ação poderá ser proposta no foro do local do fato ou do dano e, se não forem conhecidos, no foro da situação dos bens ou do domicílio do réu. A propositura da ação prevenirá a competência do juízo para todas as ações de perda civil posteriores que possuam a mesma causa de pedir ou o mesmo objeto.', '["Foro do fato ou do dano; subsidiariamente, da situação dos bens ou do domicílio do réu.","A primeira ação previne a competência para as demais com mesma causa de pedir ou objeto."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'Duas ações sobre o mesmo patrimônio ficam no mesmo juízo.', '["Assertiva que fixa o foro exclusivamente no domicílio do réu erra: a regra principal é o local do fato ou do dano."]'::jsonb, '[{"termo":"Prevenção","significado":"O juízo da primeira ação fica competente para as seguintes ligadas a ela."}]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ação comportará, a qualquer tempo, a concessão de medidas de urgência necessárias para garantir a eficácia do provimento final, mesmo que ainda não identificado o titular dos bens. As medidas preparatórias perderão a eficácia se a ação não for proposta em 365 dias, prorrogáveis por igual período mediante decisão fundamentada. Os pedidos de liberação serão examinados caso a caso, e o juiz poderá determinar atos de conservação. Realizada a constrição, o juiz deliberará sobre a alienação antecipada ou a nomeação de administrador, e o processo terá prioridade de tramitação.', '["Medidas de urgência a qualquer tempo.","Medidas preparatórias perdem eficácia em 365 dias sem ação, prorrogáveis.","Liberação examinada caso a caso.","Alienação antecipada ou administrador após a constrição.","Prioridade de tramitação."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Prazo de 365 dias para propor a ação principal."]'::jsonb, 'O juiz bloqueia o imóvel em urgência, e o Ministério Público tem 365 dias para propor a ação.', '["Assertiva que fixa em 30 dias o prazo para propor a ação principal erra: são 365 dias, prorrogáveis."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, quando necessário, após ouvir o Ministério Público, nomeará pessoa física ou jurídica qualificada para a administração dos bens, direitos ou valores sujeitos a medidas de urgência, mediante termo de compromisso.', '["Nomeação de administrador qualificado, após ouvir o MP.","Termo de compromisso."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'O juiz nomeia um administrador para cuidar de uma fazenda bloqueada.', '["Assertiva que dispensa a oitiva do MP na nomeação erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa responsável pela administração dos bens fará jus à remuneração de até 10% do valor dos bens envolvidos, fixada pelo juiz e satisfeita preferencialmente com os frutos dos bens; prestará contas periodicamente, quando destituída, ao fim do processo de conhecimento e sempre que o juiz determinar; realizará os atos de manutenção, inclusive seguro, vedada a alienação de domínio; e poderá ceder onerosamente a utilização dos bens a terceiros, com seguro pelo cessionário, se o juiz determinar.', '["Remuneração de até 10% do valor dos bens.","Prestação de contas periódica.","Manutenção dos bens e seguro, sem alienar.","Cessão onerosa com seguro."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Teto de 10% e vedação de alienação."]'::jsonb, 'O administrador aluga um imóvel bloqueado e usa os frutos para pagar sua remuneração.', '["Assertiva que autoriza o administrador a vender os bens erra: é vedada a alienação de domínio."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Julgado procedente o pedido, o juiz determinará as medidas necessárias à transferência definitiva dos bens, direitos ou valores. Se o pedido for julgado improcedente por insuficiência de provas, qualquer legitimado poderá propor nova ação com idêntico fundamento, desde que instruída com nova prova.', '["Procedência: transferência definitiva dos bens.","Improcedência por falta de provas: nova ação com nova prova."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","A coisa julgada, nesse caso, não impede nova ação com nova prova."]'::jsonb, 'A ação perdida por falta de prova pode ser reproposta quando surgir novo documento.', '["Assertiva que impede qualquer nova ação após a improcedência por falta de provas erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ação civil de perdimento, não haverá adiantamento de custas, emolumentos, honorários periciais e outras despesas, nem condenação do autor, salvo má-fé comprovada, em honorários de advogado, custas e despesas. A perícia será realizada preferencialmente por peritos da administração pública. Se for imprescindível perito externo, as despesas serão adiantadas pelo ente interessado e, ao final, pagas pelo réu vencido ou pelo ente.', '["Sem adiantamento de custas ao autor.","Sem condenação do autor em honorários e custas, salvo má-fé.","Perícia preferencialmente por peritos públicos.","Perito externo: despesas adiantadas pelo ente."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'O Ministério Público propõe a ação sem pagar custas antecipadas.', '["Assertiva que condena o autor em honorários mesmo sem má-fé erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de procedência definitiva do pedido, os recursos auferidos com a declaração de perda civil de bens e as multas previstas na Lei serão incorporados ao domínio da União, dos Estados, do Distrito Federal ou dos Municípios, conforme o caso. Na hipótese de improcedência, os valores, corrigidos monetariamente, serão restituídos ao seu titular.', '["Procedência: recursos incorporados ao ente federativo.","Improcedência: restituição com correção monetária."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'Se a ação fracassa, o valor bloqueado volta ao titular com correção.', '["Assertiva que dispensa a correção na devolução dos valores erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O terceiro que, não sendo réu na ação penal correlata, espontaneamente prestar informações ou fornecer provas relevantes para o esclarecimento dos fatos da ação de perdimento e colaborar de modo eficaz para a localização dos bens fará jus à retribuição de até 5% do produto obtido com a liquidação dos bens. A retribuição será fixada na sentença, de modo fundamentado.', '["Retribuição ao terceiro colaborador de até 5% do produto da liquidação.","O colaborador não pode ser réu na ação penal correlata.","Fixada na sentença, de modo fundamentado."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Teto de 5%."]'::jsonb, 'Quem informa onde estão bens ocultos da facção pode receber parte do que for apurado.', '["Assertiva que admite a retribuição ao réu da ação penal erra: o colaborador é terceiro."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituído o Banco Nacional de Dados de Organizações Criminosas Ultraviolentas, Grupos Paramilitares ou Milícias Privadas, a ser regulamentado por ato do Poder Executivo federal no prazo de até 180 dias da publicação da Lei, com a finalidade de identificar, registrar e manter base de dados unificada sobre pessoas físicas e jurídicas integrantes, colaboradoras ou financiadoras. Estados e Distrito Federal devem criar bancos estaduais, interoperáveis e atualizados em tempo real. A criação do banco estadual é condição para convênios e repasses voluntários da União no âmbito do Susp. A inclusão ou remoção observa critérios objetivos fixados de forma colegiada. A inclusão formalizada presume o vínculo da pessoa com a organização para fins administrativos, operacionais e de cooperação institucional.', '["Banco nacional regulamentado em até 180 dias.","Bancos estaduais obrigatórios e interoperáveis.","Criação do banco estadual é condição para repasses da União.","Inclusão presume o vínculo para fins administrativos e operacionais."]'::jsonb, '["ATUALIZAÇÃO: lei recente; verifique a regulamentação do banco.","Presunção de vínculo apenas para fins administrativos, operacionais e de cooperação."]'::jsonb, 'O Estado só recebe repasses voluntários se integrar o banco de dados de facções.', '["Assertiva que fixa em 90 dias o prazo para regulamentar o banco nacional erra: são 180 dias."]'::jsonb, '[{"termo":"Susp","significado":"Sistema Único de Segurança Pública."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão cautelar ou o cumprimento de pena privativa de liberdade em regime fechado de qualquer membro de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, em razão dos crimes da Lei, não será considerada para a concessão de auxílio-reclusão, previsto no art. 80 da Lei nº 8.213, de 24 de julho de 1991.', '["Prisão cautelar ou regime fechado por esses crimes não gera auxílio-reclusão."]'::jsonb, '["ATUALIZAÇÃO: lei recente; reforça a vedação do §6º do art. 2º."]'::jsonb, 'A família do preso por domínio social estruturado não recebe auxílio-reclusão.', '["Assertiva que assegura auxílio-reclusão a dependentes do preso por esses crimes erra."]'::jsonb, '[]'::jsonb, '["Art. 2º, §6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-30'
