insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As disposições da Lei não afastam a aplicação das medidas de retenção, apreensão, perdimento e destinação de bens pela Secretaria Especial da Receita Federal do Brasil, pelo Banco Central do Brasil ou por quaisquer órgãos que possuam regramentos próprios ou constantes de leis específicas aplicadas no processo administrativo.', '["Não afasta medidas administrativas da Receita e do Banco Central.","Permanecem os regramentos próprios de outros órgãos."]'::jsonb, '["ATUALIZAÇÃO: lei recente."]'::jsonb, 'A Receita continua podendo reter e apreender mercadorias pelo processo administrativo.', '["Assertiva que revoga os poderes administrativos de perdimento da Receita erra."]'::jsonb, '[]'::jsonb, '["Art. 9º, §2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se aos crimes da Lei, no que couber, os instrumentos de investigação e meios de obtenção de provas previstos no Capítulo II da Lei de Organizações Criminosas.', '["Colaboração premiada, ação controlada, infiltração e outros meios de prova."]'::jsonb, '["ATUALIZAÇÃO: lei recente; repete a ideia do art. 8º."]'::jsonb, 'A polícia pode infiltrar agentes na facção, nos termos da Lei de Organizações Criminosas.', '["Assertiva que exclui a infiltração de agentes nos crimes desta Lei erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
