insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera o Código Penal para endurecer o tratamento de crimes cometidos por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas do art. 2º. Entre as mudanças: perda dos instrumentos do crime em favor da União, do Estado ou do Distrito Federal; suspensão por 180 dias do CNPJ do estabelecimento usado na prática do crime; homicídio doloso com reclusão de vinte a quarenta anos; lesão corporal seguida de morte com reclusão de vinte a quarenta anos; ameaça com reclusão de um a três anos; sequestro e cárcere privado com reclusão de doze a vinte anos; furto com reclusão de quatro a dez anos e multa; roubo com pena aplicada em triplo; e outros crimes patrimoniais com agravamentos.', '["Altera o Código Penal para agravar crimes de integrante de facção.","Homicídio doloso: reclusão de vinte a quarenta anos.","Sequestro: reclusão de doze a vinte anos.","Roubo: pena aplicada em triplo.","Perda dos instrumentos e suspensão do CNPJ por 180 dias."]'::jsonb, '["ATUALIZAÇÃO: este artigo modifica outras leis; confira a redação vigente do Código Penal.","Vale somente quando o crime se dá no contexto da atuação da facção."]'::jsonb, 'Homicídio cometido por integrante de facção para os fins do art. 2º tem reclusão de vinte a quarenta anos.', '["Assertiva que aplica o agravamento a qualquer homicídio, independentemente do contexto, erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O parágrafo único do art. 1º da Lei dos Crimes Hediondos passa a vigorar acrescido do inciso VIII, que inclui como hediondos os crimes de domínio social estruturado e de favorecimento ao domínio social estruturado, previstos no caput e nos §§1º e 3º do art. 2º e no art. 3º da Lei.', '["Inclui os crimes desta Lei no rol da Lei dos Crimes Hediondos.","Inciso VIII acrescentado ao parágrafo único do art. 1º."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei dos Crimes Hediondos."]'::jsonb, 'O crime de domínio social estruturado entra no rol dos hediondos.', '["Assertiva que não considera hediondo o domínio social estruturado erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera a Lei de Execução Penal. Prevê o monitoramento audiovisual e a gravação de encontros no parlatório ou por meio virtual entre presos ligados a organizações ultraviolentas e seus visitantes, a pedido do delegado, do MP ou da administração penitenciária. Quando houver razões fundadas de conluio criminoso entre advogado e cliente, as comunicações monitoradas são analisadas por juízo de controle distinto do que instrui o processo. Dispõe sobre gravação de visitas, a definição do estabelecimento prisional pelo juiz em 24 horas e a transferência excepcional de presos em risco iminente. Eleva as frações para progressão de regime em crimes hediondos: 70% para o primário, 75% para quem comanda facção estruturada para crime hediondo (sem livramento condicional), 80% para o reincidente e 85% para o reincidente com resultado morte (sem livramento condicional).', '["Monitoramento de encontros e gravação de visitas.","Controle por juízo distinto quando houver conluio entre advogado e cliente.","Definição do estabelecimento em 24 horas e transferência excepcional.","Frações de progressão: 70%, 75%, 80% e 85%, conforme o caso."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Execução Penal; confira a redação vigente.","Livramento condicional vedado nas hipóteses indicadas."]'::jsonb, 'O líder de facção condenado por crime hediondo cumpre 75% da pena para progredir de regime.', '["Assertiva que fixa em 40% a fração de progressão do primário em crime hediondo, nessa Lei, erra: o texto prevê 70%."]'::jsonb, '[]'::jsonb, '["Lei de Execução Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei de Drogas passa a vigorar acrescida do art. 40-A: as penas dos arts. 33 a 37 serão aplicadas em dobro se o crime for praticado por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas do art. 2º da Lei. Aplica-se a pena do concurso material do art. 69 do Código Penal se o crime tiver sido praticado com emprego de arma de fogo, independentemente de seu uso estar ligado ao comércio de entorpecentes.', '["Penas dos arts. 33 a 37 da Lei de Drogas em dobro para integrante de facção.","Arma de fogo: aplica-se o concurso material do art. 69 do Código Penal."]'::jsonb, '["ATUALIZAÇÃO: acrescenta o art. 40-A à Lei de Drogas.","Pena em DOBRO, e não aumento fracionário."]'::jsonb, 'O traficante integrante de facção tem a pena dobrada.', '["Assertiva que prevê aumento de 1/6 a 2/3 no art. 40-A erra: a pena é aplicada em dobro."]'::jsonb, '[]'::jsonb, '["Lei de Drogas"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Estatuto do Desarmamento passa a vigorar acrescido do art. 21-A: nos crimes dos arts. 12, 14 e 16, a pena é aumentada de 2/3 se o crime for praticado em concurso com crime da Lei de Drogas, estiver diretamente ligado ao comércio ilícito de entorpecentes ou o artefato tiver sido utilizado para assegurar o sucesso da mercancia.', '["Aumento de 2/3 nos arts. 12, 14 e 16 do Estatuto do Desarmamento.","Concurso com Lei de Drogas ou ligação ao comércio de entorpecentes."]'::jsonb, '["ATUALIZAÇÃO: acrescenta o art. 21-A ao Estatuto do Desarmamento."]'::jsonb, 'A arma usada para proteger o ponto de venda de drogas sofre aumento de 2/3.', '["Assertiva que aplica o aumento ao art. 15 do Estatuto erra: o texto cita os arts. 12, 14 e 16."]'::jsonb, '[]'::jsonb, '["Estatuto do Desarmamento"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera o Código de Processo Penal. A audiência de custódia passa a ser realizada em até 24 horas por videoconferência em tempo real, com defesa técnica e Ministério Público, direito a entrevista prévia e privacidade do preso, repetição completa em caso de falha do sistema e salas próprias nos estabelecimentos; em situações excepcionais de força maior pode ser presencial. Nos homicídios cometidos por membros de organizações ultraviolentas, a competência do júri não prevalece sobre outro órgão na conexão. A prisão preventiva é admitida quando o crime for cometido por integrante de organização ultraviolenta no contexto de sua atuação. Prevê ainda efeito suspensivo ou ativo em recurso contra a decisão que concede, nega ou revoga a liberdade provisória.', '["Audiência de custódia por videoconferência em até 24 horas.","Garantias de defesa, privacidade e repetição em falha do sistema.","Competência do júri não prevalece sobre outro órgão em homicídio ligado à facção.","Prisão preventiva admitida para integrante de facção.","Efeito suspensivo ou ativo em recurso do inciso V do art. 581."]'::jsonb, '["ATUALIZAÇÃO: altera o Código de Processo Penal; confira a redação vigente.","Exceção presencial só por força maior."]'::jsonb, 'A audiência de custódia ocorre por videoconferência em até 24 horas da prisão.', '["Assertiva que torna a audiência de custódia, nessa Lei, sempre presencial erra: é por videoconferência, salvo força maior."]'::jsonb, '[]'::jsonb, '["Código de Processo Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei de Lavagem de Dinheiro passa a vigorar com alterações no art. 4º-A, ajustando a disciplina do depósito do produto da alienação antecipada de bens: nos processos da Justiça Federal e das Justiças dos Estados e do Distrito Federal, define os destinos do valor após o trânsito em julgado da sentença condenatória, que é incorporado ao patrimônio da União ou do ente federativo.', '["Altera o art. 4º-A da Lei de Lavagem.","Ajusta o destino dos valores da alienação antecipada."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Lavagem de Dinheiro; confira a redação vigente."]'::jsonb, 'Após a condenação, o valor do leilão antecipado é incorporado ao patrimônio do ente.', '["Assertiva que repassa o produto ao próprio réu após a condenação erra."]'::jsonb, '[]'::jsonb, '["Lei de Lavagem de Dinheiro"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Eleitoral passa a vigorar com alterações: no art. 5º, a inclusão das pessoas recolhidas a estabelecimento prisional, enquanto perdurar a privação de liberdade, ainda que sem condenação definitiva; e no art. 71, a inclusão da prisão provisória, em quaisquer de suas modalidades, entre as hipóteses de cancelamento ou suspensão.', '["Altera o Código Eleitoral.","Pessoas presas, ainda sem condenação definitiva, entram no rol do art. 5º.","Prisão provisória entra no rol do art. 71."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Eleitoral; confira a redação vigente e sua compatibilidade com a Constituição."]'::jsonb, 'O texto trata dos efeitos da prisão sobre a inscrição eleitoral.', '["Assertiva que exclui a prisão provisória do art. 71 do Código Eleitoral, nessa alteração, erra."]'::jsonb, '[]'::jsonb, '["Código Eleitoral"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-40'
