insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 13.756, de 12 de dezembro de 2018, passa a vigorar com alterações: o Fundo Nacional de Segurança Pública apoia projetos, atividades e ações em segurança pública e prevenção à violência, no enfrentamento do crime organizado e na expansão, modernização e qualificação do sistema prisional, inclusive quanto à segregação de lideranças. A gestão cabe ao Ministério da Justiça e Segurança Pública, e as ações observarão o Plano Nacional de Segurança Pública e Defesa Social. Altera ainda as fontes do fundo.', '["Altera a Lei do Fundo Nacional de Segurança Pública.","Inclui enfrentamento do crime organizado e sistema prisional.","Gestão do Ministério da Justiça e Segurança Pública."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 13.756, de 12 de dezembro de 2018."]'::jsonb, 'Recursos do fundo apoiam a segregação de lideranças de facções no sistema prisional.', '["Assertiva que atribui a gestão do FNSP ao Ministério da Fazenda erra: é do Ministério da Justiça e Segurança Pública."]'::jsonb, '[{"termo":"FNSP","significado":"Fundo Nacional de Segurança Pública."}]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
