insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 14.790, de 29 de dezembro de 2023, passa a vigorar com alterações: constatada a exploração de loteria de apostas de quota fixa por pessoa não autorizada, instituições financeiras e de pagamento devem bloquear as contas dos operadores irregulares e impedir novas transações, respeitado o devido processo administrativo e o ressarcimento dos apostadores. Valores perdidos em favor da União têm destinação vinculada ao Fundo Nacional de Segurança Pública. As instituições devem ainda integrar-se a sistemas de compartilhamento de informações sobre fraudes eletrônicas.', '["Bloqueio de contas de operadores irregulares de apostas.","Devido processo administrativo e ressarcimento dos apostadores.","Destinação dos valores perdidos ao FNSP.","Integração aos sistemas de informações sobre fraudes."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 14.790, de 29 de dezembro de 2023 (apostas de quota fixa)."]'::jsonb, 'O banco bloqueia as contas de uma casa de apostas que opera sem autorização.', '["Assertiva que dispensa o devido processo administrativo no bloqueio erra."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
