insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade emitida por órgãos de Identificação dos Estados, do Distrito Federal e dos Territórios tem fé pública e validade em todo o território nacional.', '["Emitida pelos órgãos de identificação estaduais, distritais e territoriais.","Tem fé pública.","Validade em todo o território nacional."]'::jsonb, '["A validade nacional independe do Estado emissor."]'::jsonb, 'A identidade emitida em um Estado vale em qualquer outro.', '["Assertiva que restringe a validade da identidade ao Estado emissor erra: vale em todo o território nacional."]'::jsonb, '[{"termo":"Fé pública","significado":"Presunção de veracidade do documento."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
