insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a expedição da Carteira de Identidade não será exigida do interessado a apresentação de qualquer outro documento, além da certidão de nascimento ou de casamento. A requerente do sexo feminino apresentará obrigatoriamente a certidão de casamento, caso seu nome de solteira tenha sido alterado em consequência do matrimônio. O brasileiro naturalizado apresentará o Certificado de Naturalização. A primeira emissão da Carteira de Identidade é gratuita.', '["Basta a certidão de nascimento ou de casamento.","Quem mudou o nome pelo casamento apresenta a certidão de casamento.","Naturalizado apresenta o Certificado de Naturalização.","Primeira emissão gratuita."]'::jsonb, '["ATUALIZAÇÃO: o §3º (gratuidade da primeira emissão) foi incluído por lei posterior.","Nenhum outro documento pode ser exigido."]'::jsonb, 'O cidadão obtém a primeira identidade sem pagar taxa, apresentando a certidão de nascimento.', '["Assertiva que cobra taxa da primeira emissão da identidade erra: ela é gratuita."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identidade' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade conterá as Armas da República e a inscrição República Federativa do Brasil; o nome da Unidade da Federação; a identificação do órgão expedidor; o registro geral, local e data da expedição; nome, filiação, local e data de nascimento e dados resumidos do registro de nascimento; fotografia 3 x 4, assinatura e impressão digital do polegar direito; assinatura do dirigente do órgão; e o número do CPF. Na emissão de novos documentos, o órgão deve usar o número do CPF como número de registro geral, pesquisar a base do CPF para verificar a integridade das informações e disponibilizar dados cadastrais e biométricos à Receita Federal. Se o requerente não tiver CPF, o órgão fará a inscrição.', '["Elementos obrigatórios do documento.","Fotografia 3 x 4, assinatura e impressão digital do polegar direito.","Número do CPF.","CPF como número de registro geral nos novos documentos.","Órgão inscreve no CPF quem ainda não tiver."]'::jsonb, '["ATUALIZAÇÃO: CPF como registro geral e a Carteira de Identidade Nacional decorrem de alterações recentes.","Impressão digital do polegar DIREITO."]'::jsonb, 'A nova identidade traz o CPF como número de registro geral.', '["Assertiva que prevê a impressão digital do polegar esquerdo erra: é do polegar direito."]'::jsonb, '[{"termo":"Registro geral","significado":"Número de cadastro do cidadão no órgão emissor (RG)."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identidade' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desde que o interessado o solicite, a Carteira de Identidade conterá, além dos elementos do art. 3º, os números de inscrição do titular no PIS ou no PASEP e no CPF. O Poder Executivo Federal poderá aprovar a inclusão de outros dados opcionais. A inclusão poderá ser parcial e dependerá exclusivamente da apresentação dos respectivos documentos comprobatórios.', '["PIS ou PASEP e CPF, a pedido do interessado.","Outros dados opcionais, por aprovação do Executivo.","Inclusão parcial e mediante documentos comprobatórios."]'::jsonb, '["Dados OPCIONAIS dependem de pedido do titular."]'::jsonb, 'O cidadão pede que o número do PIS conste na sua identidade.', '["Assertiva que torna obrigatória a inclusão do PIS na identidade erra: depende de solicitação."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identidade' and u.unit_key = 'art-4'
