insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão temporária será decretada pelo juiz, em face da representação da autoridade policial ou de requerimento do Ministério Público, e terá o prazo de 5 dias, prorrogável por igual período em caso de extrema e comprovada necessidade. Na representação da autoridade policial, o juiz ouvirá antes o Ministério Público. O despacho será fundamentado e prolatado dentro de 24 horas do recebimento. O juiz poderá determinar que o preso lhe seja apresentado e submetê-lo a exame de corpo de delito. Expede-se mandado em duas vias, uma entregue ao indiciado como nota de culpa, e o mandado conterá o período de duração e o dia da libertação. A prisão só pode ser executada após o mandado judicial. Efetuada a prisão, a autoridade informará o preso de seus direitos constitucionais. Decorrido o prazo, a autoridade custodiante deve soltar o preso, independentemente de nova ordem, salvo comunicação de prorrogação ou de prisão preventiva. O dia do cumprimento do mandado entra no cômputo do prazo.', '["Decretada pelo juiz, por representação da autoridade policial ou requerimento do MP.","Prazo de 5 dias, prorrogável por igual período.","Despacho fundamentado em 24 horas.","Mandado em duas vias, com duração e dia da libertação.","Soltura automática ao fim do prazo.","Dia do cumprimento do mandado conta no prazo."]'::jsonb, '["ATUALIZAÇÃO: §§4º-A, 7º e 8º incluídos pela Lei nº 13.869, de 2019 (Lei de Abuso de Autoridade).","O juiz NÃO decreta de ofício.","Crimes hediondos e equiparados têm prazo próprio, mais longo (veja a Lei dos Crimes Hediondos) (Lei dos Crimes Hediondos)."]'::jsonb, 'O delegado representa pela prisão temporária, o juiz ouve o MP e decide em 24 horas.', '["Assertiva que permite ao juiz decretar a prisão temporária de ofício erra: depende de representação ou requerimento."]'::jsonb, '[]'::jsonb, '["Art. 1º","Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'temporaria' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

